function plotMetrics(containerId) {
  const el = document.getElementById(containerId);
  if (!el) return;
  const recent = METRICS_HISTORY.slice(-60);
  const maxRps = Math.max(...recent.map(m => m.rps));
  const bars = recent.map(m => {
    const pct = Math.round((m.rps / maxRps) * 100);
    return '<div style="display:inline-block;width:1.5%;height:' + pct +
           'px;background:#38bdf8;margin:0 .5px;vertical-align:bottom;' +
           'title=' + m.rps + ' rps"></div>';
  }).join('');
  el.innerHTML = '<div style="height:120px;display:flex;' +
    'align-items:flex-end;gap:1px">' + bars + '</div>';
}
document.addEventListener('DOMContentLoaded', () => {
  plotMetrics('metrics-chart');
  const avg = (METRICS_HISTORY.reduce((a,m)=>a+m.latency,0)/METRICS_HISTORY.length).toFixed(1);
  const el = document.getElementById('avg-latency');
  if (el) el.textContent = avg + ' ms';
});
